@prefix m: <urn:example:mapping/json#>.
@prefix m1: <urn:example:mapping/xml#>.
@prefix mork: <http://www.nebularis.org/ontologies/Mork#>.
@prefix sh: <http://www.w3.org/ns/shacl#>.
@prefix skos: <http://www.w3.org/2004/02/skos/core#>.
@prefix src: <urn:example:source/json#>.
@prefix src1: <urn:example:source/xml#>.
@prefix tgt: <urn:example:target#>.
@prefix xsd: <http://www.w3.org/2001/XMLSchema#>.

m:FireRow a mork:DataMapping;
    mork:compositeBroaderMapping m:Peril;
    mork:exactABoxMatch tgt:Fire;
    mork:mappingFor src:Fire;
    mork:mappingScheme m:Scheme.
m:FloodRow a mork:DataMapping;
    mork:compositeBroaderMapping m:Peril;
    mork:exactABoxMatch tgt:Flood;
    mork:mappingFor src:Flood;
    mork:mappingScheme m:Scheme.
m:Holder a mork:DataMapping;
    mork:compositeBroaderMapping m:Policy;
    mork:dataRef "holder";
    mork:exactRBoxMatch tgt:holderName;
    mork:mappingScheme m:Scheme.
m:Insurer a mork:DataMapping;
    mork:compositeBroaderMapping m:Policy;
    mork:exactABoxMatch tgt:Acme;
    mork:inverseRBoxMatch tgt:insures;
    mork:mappingScheme m:Scheme.
m:Peril a mork:DataMapping;
    mork:compositeBroaderMapping m:Cover;
    mork:dataRef "code";
    mork:exactRBoxMatch tgt:peril;
    mork:mappingScheme m:Scheme.
m:Status a mork:DataMapping;
    mork:compositeBroaderMapping m:Policy;
    mork:dataInline "active";
    mork:exactRBoxMatch tgt:status;
    mork:mappingScheme m:Scheme.
m1:FireRow a mork:DataMapping;
    mork:compositeBroaderMapping m1:Peril;
    mork:exactABoxMatch tgt:Fire;
    mork:mappingFor src1:Fire;
    mork:mappingScheme m1:Scheme.
m1:FloodRow a mork:DataMapping;
    mork:compositeBroaderMapping m1:Peril;
    mork:exactABoxMatch tgt:Flood;
    mork:mappingFor src1:Flood;
    mork:mappingScheme m1:Scheme.
m1:Holder a mork:DataMapping;
    mork:compositeBroaderMapping m1:Policy;
    mork:dataRef "p:holder";
    mork:exactRBoxMatch tgt:holderName;
    mork:mappingScheme m1:Scheme.
m1:Insurer a mork:DataMapping;
    mork:compositeBroaderMapping m1:Policy;
    mork:exactABoxMatch tgt:Acme;
    mork:inverseRBoxMatch tgt:insures;
    mork:mappingScheme m1:Scheme.
m1:Peril a mork:DataMapping;
    mork:compositeBroaderMapping m1:Cover;
    mork:dataRef "p:code";
    mork:exactRBoxMatch tgt:peril;
    mork:mappingScheme m1:Scheme.
m1:Status a mork:DataMapping;
    mork:compositeBroaderMapping m1:Policy;
    mork:dataInline "active";
    mork:exactRBoxMatch tgt:status;
    mork:mappingScheme m1:Scheme.
m:Cover a mork:Datum;
    mork:compositeBroaderMapping m:Policy;
    mork:conceptName "cover";
    mork:exactRBoxMatch tgt:coverOf;
    mork:exactTBoxMatch tgt:Cover;
    mork:mappingFor src:Cover;
    mork:mappingScheme m:Scheme.
m:Policy a mork:Datum;
    mork:conceptName "policy";
    mork:dataRef "number";
    mork:exactTBoxMatch tgt:Policy;
    mork:mappingFor src:Policy;
    mork:mappingScheme m:Scheme.
m1:Cover a mork:Datum;
    mork:compositeBroaderMapping m1:Policy;
    mork:conceptName "cover";
    mork:exactRBoxMatch tgt:coverOf;
    mork:exactTBoxMatch tgt:Cover;
    mork:mappingFor src1:Cover;
    mork:mappingScheme m1:Scheme.
m1:Policy a mork:Datum;
    mork:conceptName "policy";
    mork:dataRef "@number";
    mork:exactTBoxMatch tgt:Policy;
    mork:mappingFor src1:Policy;
    mork:mappingScheme m1:Scheme.
m:Scheme a mork:MappingScheme.
m1:Scheme a mork:MappingScheme;
    sh:declare [
  sh:namespace "urn:example:policy"^^xsd:anyURI;
  sh:prefix "p"
].
src:Source a mork:RepresentationScheme;
    mork:format mork:JSON;
    skos:example "{\"policies\": [\n  {\"number\": \"P-1\", \"holder\": \"Ann \\\"Annie\\\" Lee\", \"covers\": [{\"code\": \"FIRE\"}, {\"code\": \"FLOOD\"}]},\n  {\"number\": \"P-2\", \"holder\": \"Bo\", \"covers\": [{\"code\": \"FIRE\"}, {\"code\": \"QUAKE\"}]}\n]}\n".
src1:Source a mork:RepresentationScheme;
    mork:format mork:XML;
    skos:example "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!-- SPDX-License-Identifier: CC-BY-SA-4.0 -->\n<p:policies xmlns:p=\"urn:example:policy\">\n  <p:policy number=\"P-1\">\n    <p:holder>Ann \"Annie\" Lee</p:holder>\n    <p:cover><p:code>FIRE</p:code></p:cover>\n    <p:cover><p:code>FLOOD</p:code></p:cover>\n  </p:policy>\n  <p:policy number=\"P-2\">\n    <p:holder>Bo</p:holder>\n    <p:cover><p:code>FIRE</p:code></p:cover>\n    <p:cover><p:code>QUAKE</p:code></p:cover>\n  </p:policy>\n</p:policies>\n".
src:Cover a skos:Concept;
    mork:path "covers[*]";
    skos:inScheme src:Source.
src:Fire a skos:Concept;
    skos:inScheme src:Source;
    skos:notation "FIRE".
src:Flood a skos:Concept;
    skos:inScheme src:Source;
    skos:notation "FLOOD".
src:Policy a skos:Concept;
    mork:path "$.policies[*]";
    skos:inScheme src:Source.
src1:Cover a skos:Concept;
    mork:path "p:cover";
    skos:inScheme src1:Source.
src1:Fire a skos:Concept;
    skos:inScheme src1:Source;
    skos:notation "FIRE".
src1:Flood a skos:Concept;
    skos:inScheme src1:Source;
    skos:notation "FLOOD".
src1:Policy a skos:Concept;
    mork:path "/p:policies/p:policy";
    skos:inScheme src1:Source.

